// Get all incoming items
const items = $input.all();

const validMemberships = [
  "1 Month",
  "3 Months",
  "6 Months",
  "1 Year"
];

const validPaymentMethods = [
  "Insta Pay",
  "Vodafone Cash",
];

// Convert date like 8/1/2005 to a real Date
function parseDate(dateString) {
  if (!dateString) return null;

  const parts = String(dateString).trim().split(/[\/\-]/);

  if (parts.length !== 3) return null;

  const month = Number(parts[0]);
  const day = Number(parts[1]);
  const year = Number(parts[2]);

  if (
    !Number.isInteger(day) ||
    !Number.isInteger(month) ||
    !Number.isInteger(year)
  ) {
    return null;
  }

  const date = new Date(year, month - 1, day);

  // Make sure JS didn't auto-correct an invalid date
  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day
  ) {
    return null;
  }

  return date;
}

return items.map(item => {

  const data = item.json;

  // -------------------------
  // Clean basic text fields
  // -------------------------

  const fullName = String(data.full_name || "")
    .trim()
    .replace(/\s+/g, " ");

  const phone = String(data.phone || "")
    .trim()
    .replace(/\s+/g, "")
    .replace(/-/g, "");

  const email = String(data.email || "")
    .trim()
    .toLowerCase();

  const gender = String(data.gender || "")
    .trim();

  const membershipType = String(data.membership_type || "")
    .trim();

  const paymentMethodRaw = String(data.payment_method || "")
    .trim();

  const trainer = String(data.trainer || "")
    .trim();

  // -------------------------
  // Validate Name
  // -------------------------

  const nameWords = fullName.split(" ").filter(Boolean);

  const nameValid =
    fullName.length >= 3 &&
    nameWords.length >= 2 &&
    /^[A-Za-z\u0600-\u06FF\s]+$/.test(fullName);

  // -------------------------
  // Validate Egyptian Phone
  // -------------------------

  const phoneValid = /^01[0125]\d{8}$/.test(phone);

  // -------------------------
  // Validate Email
  // -------------------------

  const emailValid =
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  // -------------------------
  // Validate Birth Date
  // -------------------------

  const birthDate = parseDate(data.date_of_birth);

  const today = new Date();

  const birthDateValid =
    birthDate !== null &&
    birthDate <= today &&
    birthDate.getFullYear() >= 1900;

  // -------------------------
  // Validate Start Date
  // -------------------------

  const startDate = parseDate(data.start_date);

  const startDateValid =
    startDate !== null;

  // -------------------------
  // Validate Membership
  // -------------------------

  const membershipValid =
    validMemberships.includes(membershipType);

  // -------------------------
  // Validate Payment Method
  // -------------------------

  let paymentMethod = paymentMethodRaw;

  // Handle values like:
  // "Insta Pay :PHONE_NUMBER"
  if (paymentMethodRaw.includes(":")) {
    paymentMethod = paymentMethodRaw
      .split(":")[0]
      .trim();
  }

  const paymentMethodValid =
    validPaymentMethods.some(method =>
      paymentMethod.toLowerCase() === method.toLowerCase()
    );

  // -------------------------
  // Trainer is OPTIONAL
  // -------------------------

  const trainerValue =
    trainer === "" ? "No Trainer" : trainer;

  // -------------------------
  // Overall Validation
  // -------------------------

  const basicValidation =
    nameValid &&
    phoneValid &&
    emailValid &&
    birthDateValid &&
    startDateValid &&
    membershipValid &&
    paymentMethodValid;

  // -------------------------
  // Validation Errors
  // -------------------------

  const errors = [];

  if (!nameValid) {
    errors.push("Invalid or suspicious name");
  }

  if (!phoneValid) {
    errors.push("Invalid Egyptian mobile number");
  }

  if (!emailValid) {
    errors.push("Invalid email address");
  }

  if (!birthDateValid) {
    errors.push("Invalid date of birth");
  }

  if (!startDateValid) {
    errors.push("Invalid membership start date");
  }

  if (!membershipValid) {
    errors.push("Invalid membership type");
  }

  if (!paymentMethodValid) {
    errors.push("Invalid payment method");
  }

  // -------------------------
  // Return organized data
  // -------------------------

  return {
    json: {
      ...data,

      // Cleaned data
      full_name: fullName,
      phone: phone,
      email: email,
      gender: gender,
      membership_type: membershipType,
      start_date: data.start_date,
      payment_method: paymentMethod,
      trainer: trainerValue,

      // Validation results
      name_valid: nameValid,
      phone_valid: phoneValid,
      email_valid: emailValid,
      birth_date_valid: birthDateValid,
      start_date_valid: startDateValid,
      membership_valid: membershipValid,
      payment_method_valid: paymentMethodValid,

      // Final result
      basic_validation: basicValidation,

      // Error details
      validation_errors: errors,

      validation_message:
        basicValidation
          ? "Basic validation passed"
          : errors.join(" | ")
    }
  };
});

