const items = $input.all();

return items.map(item => {
  const data = item.json;

  const startDateString = String(data.start_date || "").trim();
  const durationMonths = Number(data.duration_months);

  const parts = startDateString.split(/[\/\-]/);

  if (parts.length !== 3) {
    throw new Error(`Invalid start date: ${startDateString}`);
  }

  const month = Number(parts[0]);
  const day = Number(parts[1]);
  const year = Number(parts[2]);

  const startDate = new Date(year, month - 1, day);

  if (
    startDate.getFullYear() !== year ||
    startDate.getMonth() !== month - 1 ||
    startDate.getDate() !== day
  ) {
    throw new Error(`Invalid start date: ${startDateString}`);
  }

  // Calculate target year and month
  const targetMonthIndex =
    (year * 12 + (month - 1)) + durationMonths;

  const endYear = Math.floor(targetMonthIndex / 12);
  const endMonth = targetMonthIndex % 12;

  // Get last day of target month
  const lastDayOfMonth =
    new Date(endYear, endMonth + 1, 0).getDate();

  // Keep the same day when possible,
  // otherwise use the last day of the month
  const endDay = Math.min(day, lastDayOfMonth);

  const endDate =
    new Date(endYear, endMonth, endDay);

  const formattedEndDate =
    `${String(endDate.getMonth() + 1).padStart(2, "0")}/` +
    `${String(endDate.getDate()).padStart(2, "0")}/` +
    `${endDate.getFullYear()}`;

  return {
    json: {
      ...data,
      end_date: formattedEndDate
    }
  };
});

const items = $input.all();

return items.map(item => {
  const output = item.json.output || "";

  const getValue = (key) => {
    const regex = new RegExp(
      `${key}:\\s*(.*?)(?=\\n|$)`,
      "i"
    );

    const match = output.match(regex);
    return match ? match[1].trim() : "";
  };

  const toBoolean = (value) =>
    String(value).toLowerCase() === "true";

  // Get original data from the node before AI Agent
  const original = $('Code in JavaScript').item.json;

  // Find a field ignoring spaces and capitalization
  const getOriginalField = (fieldName) => {
    const key = Object.keys(original).find(
      key =>
        key.trim().toLowerCase() ===
        fieldName.trim().toLowerCase()
    );

    return key ? original[key] : "";
  };

  return {
    json: {

      // =========================
      // ORIGINAL MEMBER DATA
      // =========================

      full_name: getOriginalField("full_name"),
      phone: getOriginalField("phone"),
      date_of_birth: getOriginalField("date_of_birth"),
      email: getOriginalField("email"),
      gender: getOriginalField("gender"),
      membership_type: getOriginalField("membership_type"),
      start_date: getOriginalField("start_date"),
      payment_method: getOriginalField("payment_method"),
      trainer: getOriginalField("trainer"),

      // =========================
      // AI RAW OUTPUT
      // =========================

      ai_output: output,

      // =========================
      // AI VALIDATION
      // =========================

      ai_valid: toBoolean(
        getValue("valid")
      ),

      ai_name_valid: toBoolean(
        getValue("name_valid")
      ),

      ai_phone_valid: toBoolean(
        getValue("phone_valid")
      ),

      ai_email_valid: toBoolean(
        getValue("email_valid")
      ),

      ai_date_of_birth_valid: toBoolean(
        getValue("date_of_birth_valid")
      ),

      ai_membership_valid: toBoolean(
        getValue("membership_valid")
      ),

      ai_start_date_valid: toBoolean(
        getValue("start_date_valid")
      ),

      ai_payment_method_valid: toBoolean(
        getValue("payment_method_valid")
      ),

      ai_reason: getValue("reason")
    }
  };
});

const items = $input.all();

return items.map(item => {
  const text = String(item.json.message?.text || '').trim();
  const chatId = item.json.message?.chat?.id;

  const match = text.match(/^\/start\s+(GYM-\d+)$/i);

  if (!match) {
    throw new Error(`Invalid start command: ${text}`);
  }

  return {
    json: {
      chat_id: chatId,
      member_id: match[1]
    }
  };
});
